parameters.jsCode:
const briefData = $('Validate Brief').item.json;
const ctx = $('Hydrate Context').item.json || {};
const senderRows = $('Resolve Sender').item.json;
const senderProfile = (Array.isArray(senderRows) ? senderRows[0] : senderRows) || {};
const { brief, scenario } = briefData;

const SYSTEM_PROMPT = `Tu es un rédacteur commercial expert pour une ESN (Entreprise de Services du Numérique)
nommée Kredo Digital. Tu rédiges des messages commerciaux B2B de haute qualité.

RÈGLES ABSOLUES :
1. Tu ne dois JAMAIS inventer de chiffres, de références clients, de résultats
   quantifiés ou de noms de projets qui ne figurent pas dans le CONTEXTE fourni.
2. Tu ne dois JAMAIS mentionner d'informations listées dans la section EXCLUSIONS.
3. Tu dois respecter STRICTEMENT le niveau de langue demandé (vouvoiement/tutoiement).
4. Tu dois respecter la longueur demandée (±20% tolérance).
5. Tu ne dois JAMAIS utiliser de superlatifs creux ("leader", "unique", "révolutionnaire").
6. Tu dois produire un message naturel, pas un template générique.
7. Si le contexte est insuffisant pour un argument spécifique, reste général plutôt
   que d'inventer.

FORMAT DE SORTIE :
Tu dois répondre UNIQUEMENT en JSON valide, sans backticks, sans commentaires.
Structure obligatoire :
{
  "subjects": ["objet 1", "objet 2", "objet 3"],
  "body": "le corps complet du message",
  "key_points": ["point clé 1", "point clé 2"],
  "source_refs": ["description de chaque donnée du CONTEXTE utilisée"],
  "warnings": ["avertissement si un fait semble incertain ou si le contexte manque"]
}

Pour les invitations LinkedIn (max 300 caractères), le champ "subjects" est vide
et "body" contient uniquement le message court.`;

const SCENARIO_MISSIONS = {
  signal_outreach: `MISSION : Rédige un premier mail de prise de contact basé sur l'actualité ou le signal fourni.
L'accroche DOIT mentionner le signal de manière naturelle (félicitation, référence à l'actualité).
Le message DOIT créer un pont entre le signal et une expertise Kredo pertinente.
Ne sois pas commercial trop vite — la première interaction doit créer de la valeur.`,
  follow_up_no_reply: `MISSION : Rédige une relance après un premier message resté sans réponse.
Le message doit être plus court que le précédent.
Ne répète pas le contenu du premier message — apporte un nouvel angle ou une nouvelle valeur.
Évite les formulations passives-agressives ("je me permets de revenir", "au cas où").
Si un pitch précédent existe dans le contexte, ne reprends pas les mêmes arguments.`,
  post_meeting: `MISSION : Rédige un mail de suivi après un rendez-vous.
Le message DOIT :
- Remercier brièvement
- Résumer les points clés discutés (si disponibles dans les interactions)
- Confirmer les prochaines étapes
- Proposer une action concrète (date, livrable, mise en relation)
Ton : professionnel et engagé, pas servile.`,
  profile_submission: `MISSION : Rédige un mail présentant un profil de consultant ou candidat.
Le message DOIT :
- Contextualiser pourquoi ce profil correspond au besoin
- Mettre en avant 2-3 points forts du profil (si disponibles)
- Proposer une mise en relation ou un entretien
Ne pas survendre — le CV parle de lui-même.`,
  cross_sell: `MISSION : Rédige un mail proposant un service complémentaire à un client chez qui
une mission est déjà en cours.
L'accroche DOIT faire référence à la mission existante et à la satisfaction.
Le message doit montrer que la proposition est naturelle et cohérente, pas opportuniste.`,
  reactivation: `MISSION : Rédige un mail de reprise de contact avec un ancien client ou contact inactif.
Le message DOIT :
- Rappeler le contexte de la relation passée (si disponible)
- Apporter un élément nouveau (actualité, offre, événement)
- Ne pas être culpabilisant sur le silence
Ton : chaleureux et léger, pas commercial d'emblée.`,
  proposal_follow_up: `MISSION : Rédige une relance après l'envoi d'une proposition commerciale.
Le message DOIT :
- Ne pas simplement "prendre des nouvelles"
- Apporter un élément de valeur complémentaire
- Faciliter la décision (réponse aux objections courantes, flexibilité)
Évite la pression — l'objectif est de faciliter, pas de forcer.`,
  offer_introduction: `MISSION : Rédige un mail présentant une offre ou une practice Kredo.
Le message DOIT :
- Partir du besoin client (pas de la solution Kredo)
- Montrer la valeur métier avant la capacité technique
- Être spécifique au secteur du destinataire
Évite le catalogue — un seul angle, une seule offre, un seul bénéfice principal.`,
};

const LENGTH_RANGES = {
  ultra_short: '40-80 mots',
  concise: '80-140 mots',
  standard: '140-220 mots',
  detailed: '220-400 mots',
};

function truncate(str, max) {
  if (!str) return '';
  return String(str).length > max ? String(str).slice(0, max) + '…' : String(str);
}

const sections = [];

if (ctx.company) {
  sections.push(`-- Fiche compte --\n${ctx.company.name} · secteur : ${ctx.company.sector || 'non renseigné'} · ${truncate(ctx.company.description || '', 400)}`);
}
if (ctx.recentInteractions && ctx.recentInteractions.length) {
  const lines = ctx.recentInteractions.slice(0, 3).map(i => `${(i.occurred_at || '').slice(0,10)} · ${i.type} · ${truncate(i.summary || '', 150)}`);
  sections.push(`-- Historique commercial --\n${lines.join('\n')}`);
}
if (ctx.activeOpportunities && ctx.activeOpportunities.length) {
  const lines = ctx.activeOpportunities.slice(0, 3).map(o => `${o.need_summary || o.opportunity_type || 'opportunité'} · étape ${o.stage} · ~${o.estimated_gain || '?'}€`);
  sections.push(`-- Opportunités actives --\n${lines.join('\n')}`);
}
if (ctx.activeMissions && ctx.activeMissions.length) {
  const lines = ctx.activeMissions.slice(0, 3).map(m => `${m.title} · ${m.role_title || ''} · depuis le ${m.start_date}`);
  sections.push(`-- Missions en cours --\n${lines.join('\n')}`);
}
if (ctx.sectorNews && ctx.sectorNews.length) {
  const lines = ctx.sectorNews.map(n => `${(n.published_at || '').slice(0,10)} · ${n.title} · ${truncate(n.summary || '', 150)}`);
  sections.push(`-- Signal/Actualité sectorielle --\n${lines.join('\n')}`);
}
if (ctx.sectorIntelligence) {
  sections.push(`-- Intelligence sectorielle --\n${ctx.sectorIntelligence.name} · ${truncate(JSON.stringify(ctx.sectorIntelligence.playbook || {}), 300)}`);
}
if (ctx.previousCommunications && ctx.previousCommunications.length) {
  const lines = ctx.previousCommunications.map(p => truncate(JSON.stringify((p.content_json && (p.content_json.key_points || p.content_json.body)) || ''), 150));
  sections.push(`-- Communications précédentes --\n${lines.join('\n')}`);
}

let contextBlock = sections.join('\n\n');
const MAX_CONTEXT_CHARS = 8000;
if (contextBlock.length > MAX_CONTEXT_CHARS) {
  const priorityOrder = ['-- Communications précédentes --', '-- Intelligence sectorielle --', '-- Historique commercial --'];
  for (const marker of priorityOrder) {
    if (contextBlock.length <= MAX_CONTEXT_CHARS) break;
    const idx = sections.findIndex(s => s.startsWith(marker));
    if (idx >= 0) sections.splice(idx, 1);
    contextBlock = sections.join('\n\n');
  }
  contextBlock = truncate(contextBlock, MAX_CONTEXT_CHARS);
}

const recipient = brief.who.recipient;
const sender = brief.who.sender || {};
const senderName = sender.name || senderProfile.full_name || senderProfile.email || 'Un collaborateur Kredo';

const userPrompt = `${SCENARIO_MISSIONS[scenario] || ''}

ÉMETTEUR :
Nom : ${senderName}
Rôle : ${sender.role || senderProfile.role || ''}
${sender.practice ? `Practice : ${sender.practice}` : ''}
Entreprise : Kredo Digital — ESN premium spécialisée en Data/IA, Cloud, Product Management et Cybersécurité

DESTINATAIRE :
Nom : ${recipient.displayName || 'Non renseigné'}
Fonction : ${recipient.persona || ''}
Entreprise : ${recipient.companyName || (ctx.company && ctx.company.name) || ''}
Type de relation : ${recipient.relation || ''}

OBJECTIF DU MESSAGE :
${brief.who.objective || ''}

STYLE :
Canal : ${brief.what.channel}
Ton : ${brief.how.tone}
Langue : ${brief.how.language === 'en' ? 'Anglais' : 'Français'}
Formalité : ${brief.how.formality}
Longueur : ${LENGTH_RANGES[brief.what.length] || LENGTH_RANGES.standard}

CONTEXTE DISPONIBLE :
${contextBlock || '(contexte limité — nouveau prospect ou compte peu renseigné)'}

INSTRUCTIONS IMPÉRATIVES DE L'UTILISATEUR :
${(brief.context && brief.context.mustInclude) || '(aucune)'}

EXCLUSIONS :
${(brief.context && brief.context.mustExclude) || '(aucune)'}`;

return [{
  json: {
    ...briefData,
    resolvedContext: ctx,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt: userPrompt,
  }
}];

